import "core-js/modules/es.array.push.js";
import { computed, onMounted, reactive, ref, watch } from "vue";
import { useStore } from "vuex";
import { useRoute, useRouter } from "vue-router";
import useTranslations from "@/composables/useTranslations";
import vClickOutside from "click-outside-vue3";
import vSelect from "vue-select";
import "vue-select/dist/vue-select.css";
import axios from "axios";
import DeleteIcon from "@/Icons/DeleteIcon.vue";
import LoadPhoto from "@/Icons/LoadPhoto.vue";
import UserInfoFormBlock from "@/components/Settings/UserInfoForm/Block.vue";
export default {
  name: "SettingsMain",
  directives: {
    clickOutside: vClickOutside.directive
  },
  components: {
    UserInfoFormBlock,
    DeleteIcon,
    LoadPhoto,
    vSelect
  },
  setup() {
    const store = useStore();
    const route = useRoute();
    const router = useRouter();
    const {
      getters,
      state,
      dispatch,
      commit
    } = store;
    const emojiStatus = ref("");
    const firstName = ref("");
    const lastName = ref("");
    const phone = ref("");
    const about = ref("");
    const day = ref(1);
    const days = ref(null);
    const selectedMonth = ref(null);
    const year = ref(2000);
    const months = reactive([{
      val: 0,
      text: "Января",
      textEng: "January"
    }, {
      val: 1,
      text: "Февраля",
      textEng: "February"
    }, {
      val: 2,
      text: "Марта",
      textEng: "March"
    }, {
      val: 3,
      text: "Апреля",
      textEng: "April"
    }, {
      val: 4,
      text: "Мая",
      textEng: "May"
    }, {
      val: 5,
      text: "Июня",
      textEng: "June"
    }, {
      val: 6,
      text: "Июля",
      textEng: "July"
    }, {
      val: 7,
      text: "Августа",
      textEng: "August"
    }, {
      val: 8,
      text: "Сентября",
      textEng: "September"
    }, {
      val: 9,
      text: "Октября",
      textEng: "October"
    }, {
      val: 10,
      text: "Ноября",
      textEng: "November"
    }, {
      val: 11,
      text: "Декабря",
      textEng: "December"
    }]);
    const fileName = ref("");
    const src = ref("");
    const showEmojiStatus = ref(false);
    const itemsEmojiStatus = reactive([{
      type: "image",
      src: "/static/img/user/status_guru.png",
      alt: "Гуру кода",
      altEng: "Code guru",
      text: "Гуру кода",
      textEng: "Code guru",
      desc: "Вы уже обладаете высоким уровнем знаний и опыта в программировании.",
      descEng: "You already have a high level of knowledge and experience in programming."
    }, {
      type: "image",
      src: "/static/img/user/status_new.png",
      alt: "Новичок",
      altEng: "Beginner",
      text: "Новичок",
      textEng: "Beginner",
      desc: "Вы только начинаете изучать программирование и имеете базовые знания в этой области.",
      descEng: "You are just starting to learn programming and have basic knowledge in this field."
    }, {
      type: "image",
      src: "/static/img/user/status_escp.png",
      alt: "Экспериментатор",
      altEng: "The experimenter",
      text: "Экспериментатор",
      textEng: "The experimenter",
      desc: "Вы любите экспериментировать с новыми технологиями и методами программирования.",
      descEng: "You like to experiment with new technologies and programming methods."
    }, {
      type: "image",
      src: "/static/img/user/status_teacher.png",
      alt: "Учитель",
      altEng: "Teacher",
      text: "Учитель",
      textEng: "Teacher",
      desc: "Вы уже имеете опыт и знания в программировании и помогаете другим изучать эту область.",
      descEng: "You already have experience and knowledge in programming and are helping others to study this field."
    }, {
      type: "image",
      src: "/static/img/user/status_student.png",
      alt: "Фрилансер",
      altEng: "Freelancer",
      text: "Фрилансер",
      textEng: "Freelancer",
      desc: "Ваша работа основана на свободе и творчестве, что позволяет вам достигать успеха в своей области и наслаждаться жизнью.",
      descEng: "Your work is based on freedom and creativity, which allows you to achieve success in your field and enjoy life."
    }, {
      type: "image",
      src: "/static/img/user/status_love.png",
      alt: "Любитель",
      altEng: "Lover",
      text: "Любитель",
      textEng: "Lover",
      desc: "Вы увлекаетесь программированием и имеете базовые знания в этой области, но не являетесь профессионалом.",
      descEng: "You are interested in programming and have basic knowledge in this field, but you are not a professional."
    }]);
    const selectedEmojiStatus = ref(null);
    const srcCover = ref("");
    const profileCover = ref("");
    const country = ref("");
    const city = ref("");
    const countries = ref([]);
    const cities = ref([]);
    const currentCountry = ref({});
    const photoRef = ref(null);
    const photoCoverRef = ref(null);
    const firstNameRef = ref(null);
    const lastNameRef = ref(null);
    const openCountrySelect = ref(false);
    const {
      translationsLang
    } = useTranslations();
    const getStorage = computed(() => getters["global/storage/getStorage"]);
    const getInfo = computed(() => getters["profile/info/getInfo"]);
    const currentTranslations = computed(() => state.auth.languages.language.name);
    const phoneNumber = computed(() => phone.value.replace(/\D+/g, ""));
    const years = computed(() => Array.from({
      length: 61
    }, (value, index) => 1962 + index));
    const countryNames = computed(() => countries.value.map(country => country.title));
    const cityNames = computed(() => {
      const itemCities = cities.value.map(city => city.title);
      return itemCities.sort();
    });
    watch(openCountrySelect, newVal => {
      openCountrySelect.value = newVal;
    });
    watch(() => getInfo, newVal => {
      if (!newVal) {
        return;
      }
      setInfo();
    });
    watch(country, newVal => {
      if (newVal && newVal !== "") {
        setTimeout(() => {
          currentCountry.value = countries.value.find(country => country.title === newVal);
          loadCities(currentCountry.value.id);
          countries.value.forEach(itemCountry => {
            if (itemCountry.id === currentCountry.value.id) {
              const foundCity = itemCountry.cities.find(item => item.title === city.value);
              if (city.value && currentCountry.value && city.value !== "" && currentCountry.value.id !== foundCity.countryId) {
                city.value = "";
                country.value = "";
              }
            }
          });
        }, 500);
      } else {
        city.value = "";
        cities.value = [];
        country.value = "";
      }
    }, {
      immediate: true
    });
    watch(selectedMonth, newVal => {
      selectedMonth.value = newVal;
      days.value = selectedMonth.value.val === 1 ? year.value & 3 || !(year.value % 25) && year.value & 15 ? 28 : 29 : 30 + (selectedMonth.value.val + (selectedMonth.value.val >> 3) & 1);
    });
    onMounted(() => {
      loadCountries();
      if (route.params.showEmojiPicker) {
        showEmojiStatus.value = true;
      }
    });
    const loadCountries = () => {
      axios.get("/geo/country").then(response => {
        countries.value = response.data;
        if (getInfo.value) {
          setInfo();
        }
      }).catch(() => {});
      return;
    };
    const closeEmojiList = () => {
      showEmojiStatus.value = false;
    };
    const toggleEmojiStatus = () => {
      showEmojiStatus.value = !showEmojiStatus.value;
    };
    const currentEmojiStatus = index => {
      selectedEmojiStatus.value = index.toString();
      emojiStatus.value = index.toString();
      showEmojiStatus.value = false;
    };
    const deleteEmojiStatus = () => {
      emojiStatus.value = "";
      selectedEmojiStatus.value = "";
      dispatch("global/alert/setAlert", {
        status: "response",
        text: "Статус удалён, вы всегда сможете поставить его заново"
      });
      showEmojiStatus.value = false;
    };
    const loadCities = countryId => {
      if (!countryId) {
        city.value = null;
        return;
      }
      const itemCountry = countries.value.find(itemCountry => itemCountry.id === countryId);
      cities.value = itemCountry.cities;
      return countryId;
    };
    const submitHandler = async () => {
      let _birthDate = "none";
      if (year.value && selectedMonth.value && day.value) {
        const date = new Date(year.value, selectedMonth.value.val, day.value);
        const offset = date.getTimezoneOffset();
        const localDate = new Date(date.getTime() - offset * 60 * 1000);
        _birthDate = localDate.toISOString();
      }
      if (!firstNameRef.value.validate() && !lastNameRef.value.validate()) {
        dispatch("global/alert/setAlert", {
          status: "error",
          text: 'Поля "Имя" и "Фамилия" являются обязательными'
        });
        return;
      } else if (!firstNameRef.value.validate()) {
        dispatch("global/alert/setAlert", {
          status: "error",
          text: 'Поле "Имя" является обязательным'
        });
        return;
      } else if (!lastNameRef.value.validate()) {
        dispatch("global/alert/setAlert", {
          status: "error",
          text: 'Поле "Фамилия" является обязательным'
        });
        return;
      } else if (lastName.value.length < 3 && firstName.value.length < 3) {
        dispatch("global/alert/setAlert", {
          status: "error",
          text: "Имя и Фамилия не могут быть короче 3-ёх символов"
        });
        return;
      } else if (firstName.value.length < 3) {
        dispatch("global/alert/setAlert", {
          status: "error",
          text: "Имя не может быть короче 3-ёх символов"
        });
        return;
      } else if (lastName.value.length < 3) {
        dispatch("global/alert/setAlert", {
          status: "error",
          text: "Фамилия не может быть короче 3-ёх символов"
        });
        return;
      }
      if (fileName.value) {
        await dispatch("global/storage/apiStorage", fileName.value).then(response => {
          fileName.value = response.data.fileName;
        });
      }
      if (profileCover.value) {
        await dispatch("global/storage/apiStorage", profileCover.value).then(response => {
          profileCover.value = response.data.fileName;
        });
      }
      await dispatch("profile/info/apiChangeInfo", {
        firstName: firstName.value,
        lastName: lastName.value,
        birthDate: _birthDate,
        phone: phoneNumber.value,
        about: about.value,
        country: country.value,
        city: city.value,
        emojiStatus: selectedEmojiStatus.value === "" ? emojiStatus.value : selectedEmojiStatus.value,
        photo: fileName.value === "" ? src.value : fileName.value,
        profileCover: profileCover.value === "" ? srcCover.value : profileCover.value
      }).then(() => router.push("/profile"));
    };

    // Аватарка:
    const processFile = event => {
      [fileName.value] = event.target.files;
      const reader = new window.FileReader();
      reader.onload = e => {
        src.value = e.target.result;
      };
      reader.readAsDataURL(fileName.value);
    };
    const loadPhoto = () => {
      photoRef.value.click();
    };
    const deletePhoto = () => {
      fileName.value = "";
      src.value = "";
      commit("global/storage/setStorage", "");
    };

    // Обложка
    const processFileCoverProfile = event => {
      [profileCover.value] = event.target.files;
      const reader = new window.FileReader();
      reader.onload = e => {
        srcCover.value = e.target.result;
      };
      reader.readAsDataURL(profileCover.value);
    };
    const loadPhotoCover = () => {
      photoCoverRef.value.click();
    };
    const deletePhotoCover = () => {
      profileCover.value = "";
      srcCover.value = "";
      commit("global/storage/setStorage", "");
    };
    const setInfo = () => {
      firstName.value = getInfo.value.firstName;
      lastName.value = getInfo.value.lastName;
      src.value = getInfo.value.photo;
      srcCover.value = getInfo.value.profileCover;
      emojiStatus.value = getInfo.value.emojiStatus;
      if (getInfo.value.phone) {
        phone.value = getInfo.value.phone.replace(/^[+]?[78]/, "");
      } else phone.value = "";
      if (getInfo.value.birthDate) {
        const birthDate = new Date(getInfo.value.birthDate);
        day.value = birthDate.getDate();
        selectedMonth.value = months[birthDate.getMonth()];
        year.value = birthDate.getFullYear();
      }
      about.value = getInfo.value.about;
      if (getInfo.value.country) {
        country.value = getInfo.value.country;
        currentCountry.value = countries.value.find(country => country.title === country);
        loadCities(currentCountry.value?.id);
      }
      if (getInfo.value.city) {
        city.value = getInfo.value.city;
      }
    };
    return {
      currentCountry,
      emojiStatus,
      firstName,
      lastName,
      phone,
      about,
      day,
      year,
      months,
      src,
      showEmojiStatus,
      itemsEmojiStatus,
      srcCover,
      profileCover,
      country,
      city,
      countries,
      cities,
      photoRef,
      photoCoverRef,
      firstNameRef,
      lastNameRef,
      translationsLang,
      currentTranslations,
      years,
      countryNames,
      cityNames,
      days,
      getStorage,
      selectedMonth,
      closeEmojiList,
      toggleEmojiStatus,
      currentEmojiStatus,
      deleteEmojiStatus,
      submitHandler,
      processFile,
      loadPhoto,
      deletePhoto,
      processFileCoverProfile,
      loadPhotoCover,
      deletePhotoCover,
      openCountrySelect
    };
  }
};
